export const getFormValue = (formData: FormData, name: string, fallback = "None") => {
  const value = formData.get(name);

  return typeof value === "string" && value.length > 0 ? value : fallback;
};

export const getFormValues = (formData: FormData, name: string) =>
  formData.getAll(name).filter((value): value is string => typeof value === "string");

import { getFormValue } from "../../form/examples/form-value";
import * as React from "react";
import { toast } from "@/registry/erbium/ui/toast";

import {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireSubmit,
  QuestionnaireTitle,
} from "@/registry/erbium/ui/questionnaire";

const items = [
  {
    choices: [{ value: "incremental" }, { value: "module" }, { value: "rewrite" }],
    name: "approach",
    required: true,
  },
] as const;

const handleSubmit = (event: React.SubmitEvent<HTMLFormElement>) => {
  event.preventDefault();

  const approach = getFormValue(new FormData(event.currentTarget), "approach");

  toast.add({ description: `Approach: ${approach ?? "None"}`, title: "Approach selected" });
};

export default function QuestionnaireFreeformExample() {
  return (
    <Questionnaire
      className="mx-auto max-w-md"
      items={items}
      shortcuts="letters"
      onSubmit={handleSubmit}
    >
      <QuestionnaireItem name="approach">
        <QuestionnaireTitle>How should the agent approach this refactor?</QuestionnaireTitle>
        <QuestionnaireDescription>
          Choose a strategy or write a more specific instruction.
        </QuestionnaireDescription>
        <QuestionnaireChoices>
          <QuestionnaireChoice value="incremental">
            Make the smallest safe change
          </QuestionnaireChoice>
          <QuestionnaireChoice value="module">Refactor one module at a time</QuestionnaireChoice>
          <QuestionnaireChoice value="rewrite">
            Replace the implementation completely
          </QuestionnaireChoice>
          <QuestionnaireInput
            aria-label="Another refactoring approach"
            placeholder="Describe another approach…"
          />
        </QuestionnaireChoices>
        <QuestionnaireError />
      </QuestionnaireItem>

      <QuestionnaireActions>
        <QuestionnaireSubmit>Use this approach</QuestionnaireSubmit>
      </QuestionnaireActions>
    </Questionnaire>
  );
}

import QuestionnaireFreeform from "../examples/questionnaire-freeform";

const Example = () => <QuestionnaireFreeform />;

export default Example;
